 58→// 구분자 기반 정렬 함수
 59→func formatSymbolSort(symbol, str string) (result string) {
 60→	splitStr := strings.Split(str, symbol)
 61→	sort.Sort(sort.StringSlice(splitStr))
 62→	result = strings.Join(splitStr, symbol)
 63→	return
 64→}
